/*
 * MegaNetTutorials: the Staff Directory tutorial series (NOT ads). Three compositions share this file:
 *   MegaNetTutorialInvite     (1) invite a staff member
 *   MegaNetTutorialChange     (2) change a staff member's role or facility
 *   MegaNetTutorialDeactivate (3) deactivate a staff member
 * 1080x1920 @30fps. 0.4s lead-in, voice, 2s frozen hold after the voice.
 * Voice: public/voiceover-tutorial-<key>.mp3 (en-NG-EzinneNeural, the series voice), word timings and caption chunks in
 * src/tutorialTimings.ts, both generated by scripts/tutorial_voice.py. UI crops and frame data in public/tutorial/ and
 * src/tutorialFrames.ts, generated by scripts/tutorials/tutorial_assets.py from LOCAL captures of EHR-Cloud- (origin/main
 * e8ca779, fictional demo data, 360 CSS px viewport, console email backend). Nothing was captured from staging or production.
 *
 * Look: STYLE_GUIDE.md (light, brand blue + orange, white cards, charcoal text) plus the tutorial section: real captured UI in
 * a window inside the safe area, a "Fictional demo data" chip on every screen, drawn pieces labelled "Drawn, not captured".
 * Safe area x 80-920, y 200-1095 for content; captions end at y 1272. Scenes cross-fade (8 frames) inside a clip box.
 *
 * Debug input prop (verification only, as in the ads): 'bg' = gradients only, 'caps' = captions only, 'nocaps' = no captions,
 * 'nocaps-violate(weak)-caption' / 'violate(weak)-left|right|top|bottom' / 'violate-text' / 'lowcontrast-text' / 'smalltext' = negative controls, 'audit' = log every text node,
 * 'notext' = text made transparent ('audit' / 'notext' combine with one other mode using '+').
 */
import React, {useEffect, useState} from 'react';
import {AbsoluteFill, Audio, Easing, Freeze, Img, Sequence, continueRender, delayRender, interpolate, staticFile, useCurrentFrame} from 'remotion';
import {TIMINGS} from './tutorialTimings';
import {FRAMES, Frame} from './tutorialFrames';
import {CaptionViolation, DebugContext, GradientBg, Glow, Layer} from './fx';

export const TUT_FPS = 30;
export type TutKey = 'invite' | 'change' | 'deactivate';
const LEAD = 12; // 0.4s before the voice starts
const FADE = 8; // cross-fade between frames
const CAP_DELAY = 2; // words inside a sentence run 2 frames behind the TTS word boundaries (they lead the audible onset by ~0.05-0.15s)
export const freezeFrame = (k: TutKey) => LEAD + Math.round(TIMINGS[k].VOICE_END * TUT_FPS);
export const tutDuration = (k: TutKey) => freezeFrame(k) + 2 * TUT_FPS;

const BLUE = '#1A6DE0';
const ORANGE = '#F7941D';
const TXT_BLUE = '#1458B5';
const INK = '#1B2430';
const MUTED = '#44506A';
const WHITE = '#FFFFFF';
const FONT = 'Inter, "Inter Display", system-ui, sans-serif';
const SAFE = {x: 80, y: 200, w: 840, h: 1240};
const CLIP_H = 896; // clip box y 200-1096: 24px above the caption zone (y 1120-1272)
const COL_L = 110;
const COL_W = 780;

const ease = Easing.out(Easing.cubic);
const clamp01 = (v: number) => Math.max(0, Math.min(1, v));
const enter = (l: number, start: number, dur = 9) => interpolate(l, [start, start + dur], [0, 1], {easing: ease, extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});

/* ---------- timing: when each frame starts ---------- */

const sentenceStart = (k: TutKey, scene: number, at: number): number => {
  const S = TIMINGS[k].SENTENCES;
  const first = S.findIndex((s) => s.scene === scene);
  return LEAD + Math.round(S[first + at].start * TUT_FPS);
};
const frameStarts = (k: TutKey): number[] => FRAMES[k].map((fr, i) => (i === 0 ? 0 : sentenceStart(k, fr.scene, fr.at) - 9));
export const FRAME_STARTS: Record<TutKey, number[]> = {invite: frameStarts('invite'), change: frameStarts('change'), deactivate: frameStarts('deactivate')};

/* ---------- backgrounds (full bleed, content-free) ---------- */

const g = (x: number, y: number, r: number, color: string, drift = 30): Glow => ({x, y, r, color, drift});
const BGS: {stops: string[]; angle: number; glows: Glow[]}[] = [
  {stops: ['#FFFFFF', '#FFF1DC', '#DDEBFF'], angle: 165, glows: [g(900, 420, 460, 'rgba(247,148,29,0.22)'), g(170, 1500, 500, 'rgba(26,109,224,0.16)')]},
  {stops: ['#EAF4FF', '#D3E6FF', '#FFF2DE'], angle: 190, glows: [g(160, 430, 450, 'rgba(26,109,224,0.16)'), g(920, 1480, 500, 'rgba(247,148,29,0.14)')]},
];
const bgIndex = (fr: Frame) => (fr.kind === 'title' || fr.kind === 'steps' || fr.kind === 'end' ? 0 : 1);

const Backgrounds: React.FC<{k: TutKey}> = ({k}) => {
  const f = useCurrentFrame();
  const starts = FRAME_STARTS[k];
  const dur = tutDuration(k);
  return (
    <AbsoluteFill>
      {FRAMES[k].map((fr, i) => {
        const from = starts[i];
        if (f < from) return null;
        const r = i === 0 ? 1 : clamp01((f - from) / FADE);
        const b = BGS[bgIndex(fr)];
        return (
          <Sequence key={i} from={from} durationInFrames={dur - from} layout="none">
            <AbsoluteFill style={i === 0 ? {} : {opacity: ease(r)}}>
              <GradientBg stops={b.stops} angle={b.angle} glows={b.glows} />
            </AbsoluteFill>
          </Sequence>
        );
      })}
    </AbsoluteFill>
  );
};

